  const malformedInput = events.find((entry) => entry.payload?.type === "inputAudio");
  console.log(`malformed-input-events=${malformedInput ? 1 : 0}`);
} finally {
  stopTalkRealtimeRelaySession({
    relaySessionId: session.relaySessionId,
    connId: "proof-conn",
  });
}
