const events = [];
const realtimeAudio = [];
const transcriptionAudio = [];

const registry = createEmptyPluginRegistry();
registry.plugins.push({ id: "proof-talk", status: "loaded", format: "bundle" });
registry.realtimeVoiceProviders.push({
  pluginId: "proof-talk",
  pluginName: "proof-talk",
  source: "proof",
